'use strict';

const Agent = require('./agent');
const { kCount, kDispatch, kLabel } = require('./symbols');

class Pool extends Agent {
  constructor(size) {
    super({ label: 'pool', prefix: '*' });
    this.size = size;
  }

  // Overrides the symbol-keyed method Agent declares.
  [kDispatch](path, handler) {
    if (path.length > this.size) return false;
    handler(this.prefix + ' ' + this[kLabel] + ' ' + path + ' #' + this[kCount]);
    return true;
  }
}

module.exports = Pool;
